return {["fb201_01"]={["down"]=[[fb201_03]],["dsc"]=[[这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。]],["id"]=[[fb201_01]],["name"]=[[幽司]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb201_02"]={["dsc"]=[[这里便是阴间地府十王之秦广王的宫殿。平时若是无事，秦广王便会在殿上处理一些杂务。殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的青烟，一个青衣童子侍立于后。]],["id"]=[[fb201_02]],["name"]=[[秦广殿]],["permission"]=1,["right"]=[[fb201_03]],["role1"]=[[fb201r02_1]],["stepMusic"]=[[jiaobu]]},["fb201_03"]={["down"]=[[fb201_05]],["dsc"]=[[这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。]],["id"]=[[fb201_03]],["left"]=[[fb201_02]],["name"]=[[幽司]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb201_01]]},["fb201_04"]={["dsc"]=[[这里便是阴间地府十王之宋帝王的宫殿。平时若是无事，宋帝王便会在殿上处理一些杂务。殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的青烟，一个青衣童子侍立于后。]],["id"]=[[fb201_04]],["name"]=[[宋帝殿]],["permission"]=1,["right"]=[[fb201_05]],["role1"]=[[fb201r04_1]],["stepMusic"]=[[jiaobu]]},["fb201_05"]={["down"]=[[fb201_08]],["dsc"]=[[这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。]],["id"]=[[fb201_05]],["left"]=[[fb201_04]],["name"]=[[幽司]],["permission"]=1,["right"]=[[fb201_06]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_03]]},["fb201_06"]={["dsc"]=[[这里便是阴间地府十王之初江王的宫殿。平时若是无事，初江王便会在殿上处理一些杂务。殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的青烟，一个青衣童子侍立于后。]],["id"]=[[fb201_06]],["left"]=[[fb201_05]],["name"]=[[初江殿]],["permission"]=1,["role1"]=[[fb201r06_1]],["stepMusic"]=[[jiaobu]]},["fb201_07"]={["dsc"]=[[这里便是阴间地府十王之仵官王的宫殿。平时若是无事，仵官王便会在殿上处理一些杂务。殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的青烟，一个青衣童子侍立于后。]],["id"]=[[fb201_07]],["name"]=[[仵官殿]],["permission"]=1,["right"]=[[fb201_08]],["role1"]=[[fb201r07_1]],["stepMusic"]=[[jiaobu]]},["fb201_08"]={["down"]=[[fb201_11]],["dsc"]=[[这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。]],["id"]=[[fb201_08]],["left"]=[[fb201_07]],["name"]=[[幽司]],["permission"]=1,["right"]=[[fb201_09]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_05]]},["fb201_09"]={["dsc"]=[[这里便是阴间地府十王之平等王的宫殿。平时若是无事，平等王便会在殿上处理一些杂务。殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的青烟，一个青衣童子侍立于后。]],["id"]=[[fb201_09]],["left"]=[[fb201_08]],["name"]=[[平等殿]],["permission"]=1,["role1"]=[[fb201r09_1]],["stepMusic"]=[[jiaobu]]},["fb201_10"]={["dsc"]=[[这里便是阴间地府十王之都市王的宫殿。平时若是无事，都市王便会在殿上处理一些杂务。殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的青烟，一个青衣童子侍立于后。]],["id"]=[[fb201_10]],["name"]=[[都市殿]],["permission"]=1,["right"]=[[fb201_11]],["role1"]=[[fb201r10_1]],["stepMusic"]=[[jiaobu]]},["fb201_100"]={["down"]=[[fb201_102]],["dsc"]=[[这是一条阴冷悠长的街道，街上倒也算是热闹，来往的阴魂大多有说有笑，使人觉得恍然如在世。]],["id"]=[[fb201_100]],["name"]=[[南阴街]],["permission"]=1,["right"]=[[fb201_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_97]]},["fb201_101"]={["dsc"]=[[这是一家戏院，每日来此听戏的鬼魂数不胜数。只见纸糊的戏台上点着一对摆蜡烛，鬼戏子在上面咿咿呀呀地唱着戏，听到活人耳中都是鬼哭狼嚎。]],["id"]=[[fb201_101]],["left"]=[[fb201_100]],["name"]=[[五更转]],["permission"]=1,["role1"]=[[fb201r101_1]],["role2"]=[[fb201r101_2]],["stepMusic"]=[[jiaobu]]},["fb201_102"]={["dsc"]=[[这是一座漆黑的城门，城门上写着“下阴南门”。每隔半里便点着一盏青幽幽的灯。此时的城门大开着，站着巡守的鬼差，偶有鬼魂经过城门，便会遇到鬼差严厉的盘查。]],["id"]=[[fb201_102]],["name"]=[[上阴南门]],["permission"]=1,["role1"]=[[zx11r102_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_100]]},["fb201_103"]={["dsc"]=[[魂归司转为还阳之事而置办，但凡阴间之人要重返人界，必先至此处办理交接文书方可往返冥河。]],["id"]=[[fb201_103]],["left"]=[[fb201_71]],["name"]=[[魂归司]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb201_11"]={["down"]=[[fb201_14]],["dsc"]=[[这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。]],["id"]=[[fb201_11]],["left"]=[[fb201_10]],["name"]=[[幽司]],["permission"]=1,["right"]=[[fb201_12]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_08]]},["fb201_12"]={["dsc"]=[[这里便是阴间地府十王之泰山王的宫殿。平时若是无事，泰山王便会在殿上处理一些杂务。殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的青烟，一个青衣童子侍立于后。]],["id"]=[[fb201_12]],["item1"]=[[lylitem1]],["left"]=[[fb201_11]],["name"]=[[泰山殿]],["permission"]=1,["role1"]=[[fb201r12_1]],["stepMusic"]=[[jiaobu]]},["fb201_13"]={["dsc"]=[[这里便是阴间地府十王之轮转王的宫殿。平时若是无事，轮转王便会在殿上处理一些杂务。殿上一张大木桌，桌上堆了一些文告之类，一个小青铜炉吐着淡淡的青烟，一个青衣童子侍立于后。]],["id"]=[