d"]=[[fb201_21]],["name"]=[[阴阳塔]],["permission"]=1,["right"]=[[fb201_22]],["role1"]=[[fb201r21_1]],["role2"]=[[fb201r34_1]],["stepMusic"]=[[jiaobu]]},["fb201_22"]={["down"]=[[fb201_28]],["dsc"]=[[这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。]],["id"]=[[fb201_22]],["left"]=[[fb201_21]],["name"]=[[幽司]],["permission"]=1,["right"]=[[fb201_23]],["role1"]=[[fb201r22_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_18]]},["fb201_23"]={["down"]=[[fb201_35]],["dsc"]=[[奉祭场中有一四方高台，台上刻有日月星辰，山川大河的图腾。台上的铜鼎里偶有青烟生起，四周但见磷火阵阵，闪冒银光。四周有一座座的楼阁宫殿，看起来也相当的富丽堂皇，间有几个索命鬼，勾司人走来走去。]],["id"]=[[fb201_23]],["item1"]=[[2020qynpc1a]],["left"]=[[fb201_22]],["name"]=[[奉祭场]],["permission"]=1,["right"]=[[fb201_24]],["role1"]=[[fb201r23_1]],["role2"]=[[fb201r23_2]],["role3"]=[[fb201r23_3]],["role4"]=[[fb201r24_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_17]]},["fb201_24"]={["down"]=[[fb201_31]],["dsc"]=[[这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。]],["id"]=[[fb201_24]],["left"]=[[fb201_23]],["name"]=[[幽司]],["permission"]=1,["right"]=[[fb201_25]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_19]]},["fb201_25"]={["dsc"]=[[泗鬼门外灰蒙蒙的一片，周围一下什么也看不清了，却能听道一些急匆匆的脚步声擦身而过。隐约脚下有条道路，也不知是通向什么地方。北边一座大山，山后隐隐看到火光。]],["id"]=[[fb201_25]],["left"]=[[fb201_24]],["name"]=[[泗鬼门]],["permission"]=1,["right"]=[[fb201_26]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_20]]},["fb201_26"]={["down"]=[[fb201_33]],["dsc"]=[[这里是一条陡峭的小路，向上是背阴山，南边一座小桥，就是令人胆颤的奈何桥。能听到桥下滚滚水声，也能听到鬼狼凄叫。几个桥梁使者手握皮鞭，正驱赶着一些鬼怪。]],["id"]=[[fb201_26]],["left"]=[[fb201_25]],["name"]=[[背阴小道]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb201_27"]={["dsc"]=[[房内光线暗淡，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。]],["id"]=[[fb201_27]],["item1"]=[[fb201item27]],["name"]=[[司房]],["permission"]=1,["right"]=[[fb201_28]],["role1"]=[[fb201r27_1]],["stepMusic"]=[[jiaobu]]},["fb201_28"]={["dsc"]=[[阴司内寒气森森，黄土小径连向四方。左右分别有座青砖瓦房，偶尔有些勾司人出入。天色一片阴暗，天际现着血色。]],["id"]=[[fb201_28]],["left"]=[[fb201_27]],["name"]=[[阴司]],["permission"]=1,["right"]=[[fb201_29]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_22]]},["fb201_29"]={["dsc"]=[[房内光线暗淡，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。]],["id"]=[[fb201_29]],["left"]=[[fb201_28]],["name"]=[[司房]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb201_30"]={["dsc"]=[[房内光线暗淡，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。]],["id"]=[[fb201_30]],["name"]=[[司房]],["permission"]=1,["right"]=[[fb201_31]],["role1"]=[[fb201r30_1]],["role2"]=[[fb201r30_2]],["role3"]=[[fb201r30_3]],["stepMusic"]=[[jiaobu]]},["fb201_31"]={["dsc"]=[[阴司内寒气森森，黄土小径连向四方。左右分别有座青砖瓦房，偶尔有些勾司人出入。天色一片阴暗，天际现着血色。]],["id"]=[[fb201_31]],["left"]=[[fb201_30]],["name"]=[[阴司]],["permission"]=1,["right"]=[[fb201_32]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_24]]},["fb201_32"]={["dsc"]=[[房内光线暗淡，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。]],["id"]=[[fb201_32]],["left"]=[[fb201_31]],["name"]=[[司房]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb201_33"]={["down"]=[[fb201_37]],["dsc"]=[[这里是一条陡峭的小路，向上是背阴山，南边一座小桥，就是令人胆颤的奈何桥。能听到桥下滚滚水声，也能听到鬼狼凄叫。几个桥梁使者手握皮鞭，正驱赶着一些鬼怪。]],["id"]=[[fb201_33]],["name"]=[[背阴小路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb201_26]]},["fb201_34"]={["dsc"]=[[招魄司内寒气森森，堂周是青布围幔，上面用金银丝线绣着些奇怪的图案。堂前两侧阴兵分列，气势汹汹。堂上一张拱木案，上面摆放了些文书。]],["id"]=[[fb201_34]],["item1"]=[[2020qmzh1a]],["name"]=[[招魄司]],["permission"]=1,["right"]=[[fb201_35]],["stepMusic"]=[[jiaobu]]},["fb201_35"]={["down"]=[[fb201_64]],["dsc"]=[[这里便是阴曹地府之中，偶尔看到几个索命鬼，勾司人牵着些套着枷锁的人走来走去。周围是一座座的楼阁宫殿，看起来也相当的富丽堂皇，奇怪的是都有一扇钉着金钉的红木门和一条白玉门槛。]],["id"]=[[fb201_35]],["left"]=[[fb201_34]],["name"]=[[幽司]],["permission"]=1,["right"]=[[fb201_36]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_23]]},["fb201_36"]={["dsc"]=[[引魂司内寒气森森，堂周是青布围幔，上面用金银丝线绣着些奇怪的图案。堂前两侧阴兵分列，气势汹汹。堂上一张拱木案，上面摆放了些文书。]],["id"]=[[fb201_36]],["left"]=[[fb201_35]],["name"]=[[引魂司]],["permission"]=1,["role1"]=[[fb201r36_1]],["role2"]=[[fb201r36_2]],["stepMusic"]=[[jiaobu]]},["fb201_37"]={["down"]=[[fb201_38]],["dsc"]=[[这是一座仅数寸之宽，数丈之长的石桥。上有寒风滚滚，下是血浪滔滔。桥上左右无扶手，险峻之路如同匹练搭长江，桥下之水阴气逼人，腥风扑鼻。]],["id"]=[[fb201_37]],["item1"]=[[fb201item2]],["item2"]=[[ycitem6]],["name"]=[[奈何桥]],["permission"]=1,["role1"]=[[fb201r37_1]],["role2"]=[[fb201r37_2]],["role3"]=[[fb201r40_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_33]]},["fb201_38"]={["down"]=[[fb201_39]],["dsc"]=[[北面是奈何桥，桥后一座险峰，吹来阵阵腥风。远方传来凄凄哭声。左右俱是深涧万丈，略有闪乎就会沦如万劫不复之地而永无超生之时。]],["id"]=[[fb201_38]],["item1"]=[[fb201item3]],["item2"]=[[ycitem3]],["name"]=[[璧斗崖]],["permission"]=1,["role1"]=[[fb201r38_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_37]]},["fb201_39"]={["down"]=[[fb201_40]],["dsc"]=[[这里是一条笔直的大路，南方看起来已是一片光亮，那里便是阴阳相交的贵道门。北面却是阴云笼罩，传来阵阵悲歌的枉死城，咫尺相隔，却有天涯之别。]],["id"]=[[fb201_39]],["name"]=[[平阳大道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb201_38]]},["fb201_40"]={["dsc"]=[[这里边是阴间通往阳间的唯一出口－贵道门。若是有冤死鬼投胎，就由此出阴间。]],["id"]=[[fb201_40]],["item1"]=[[fb201item8]],["item2"]=[[fb201item51]],["item3"]=[[ycitem7]],["name"]=[[超生贵道门]],["permission"]=1,["role1"]=[[fb201r40_3]],["role2"]=[[fb201r40_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_39]]},["fb201_41"]={["down"]=[[fb201_44]],["dsc"]=[[你现在来到一座黑色城楼之前，城楼上刻着三个大字:酆都城。往北走进城楼只见一片黑漆漆的，只有少许暗红色的火光若隐若现地闪烁着。]],["id"]=[[fb201_41]],["name"]=[[酆都城门]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb201_14]]},["fb201_42"]={["dsc"]=[[周围光线一下子变暗，灰蒙蒙的一片。却能听到一些急匆匆的脚步声擦身而过。路边随处开着一些梦兰花，发出微光。隐约脚下有条道路，也不知是通向什么地方。]],["id"]=[[fb201_42]],["name"]=[[荒郊草野]],["permission"]=1,["right"]=[[fb201_43]],["role1"]=[[ycitem5]],["stepMusic"]=[[jiaobu]]},["fb201_43"]={["down"]=[[fb201_44]],["dsc"]=[[隐约北方现出一座黑色城楼，城楼上有一幅金匾，上面刻着“幽冥界”三个大字。城楼下城门紧闭，黑漆漆地什么也看不清楚。路边一个破木牌直直地指向北方，周围只有少许暗红色的火光若隐若现地闪烁着。]],["id"]=[[fb201_43]],["item1"]=[[fb201item1]],["left"]=[[fb201_54]],["name"]=[[酆都城外]],["permission"]=1,["right"]=[[fb201_55]],["stepMusic"]=[[jiaobu]]},["fb201_44"]={["down"]=[[fb201_60]],["dsc"]=[[隐约北方现出一座黑色城楼，光线太暗，看不大清楚。许多亡魂正哭哭啼啼地列队前进，因为一进鬼门关就无法再回阳间了。周围尺高的野草随风摇摆，草中发出呼呼的风声。]],["id"]=[[fb201_44]],["name"]=[[阴阳界]],["permission"]=1,["role1"]=[[fb201r44_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_43]]},["fb201_45"]={["down"]=[[fb201_46]],["dsc"]=[[前方突然开阔，一个大坑出现在你眼前。大坑里满是污秽的血水，腥臭扑鼻而来。有一些鬼魂在里面哭号，满身是血。]],["id"]=[[fb201_45]],["item1"]=[[fb201item30]],["item2"]=[[ycitem8]],["name"]=[[血水池]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb201_54]]},["fb201_46"]={["down"]=[[fb201_47]],["dsc"]=[[这里有两道山峰，在远方合为一道。抬头望去，山峰十分陡峭，其形状像锋利的刀片，山峰笔直而陡峭。山上有很多金鸡，专啄食恶鬼。山脚下是一片缓坡。]],["id"]=[[fb201_46]],["item1"]=[[fb201item56]],["item2"]=[[ycitem4]],["name"]=[[金鸡山]],["permission"]=1,["role1"]=[[fb201r46_1]],["role2"]=[[fb201r46_2]],["role3"]=[[fb201r46_3]],["role4"]=[[fb201r46_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_45]]},["fb201_47"]={["down"]=[[fb201_48]],["dsc"]=[[远远听着一阵狗叫声，山头上到处都是目光凶横，满嘴钢牙得恶犬，对来者狂吠不已。这些狗都呆在山上，偶尔有一两只跑下来，抢夺鬼魂食物。只要生前不做恶事，便不会遭到啃咬。]],["id"]=[[fb201_47]],["item1"]=[[fb201item4]],["name"]=[[恶狗岭]],["permission"]=1,["role1"]=[[fb201r47_1]],["role2"]=[[fb201r47_2]],["role3"]=[[fb201r47_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_46]]},["fb201_48"]={["down"]=[[fb201_49]],["dsc"]=[[俗话说，远望望乡台，家乡回不来。这里居中高高一个石台，发出阵阵阴光，坐卧路转之势，上可回头瞻望，书写三个赤红大字望乡台。站在望乡台上可以看见自己的家乡和亲人，台下有不少鬼魂在呜咽。]],["id"]=[[fb201_48]],["name"]=[[望乡台]],["permission"]=1,["role1"]=[[fb201r48_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_47]]},["fb201_49"]={["down"]=[[fb201_50]],["dsc"]=[[这里便是通往酆都的必经之路。站在黄泉路上，上看无日月星辰，下看无土地尘埃，前看无阳关大路，后看无亲朋四邻，凄凉无比。]],["id"]=[[fb201_49]],["item1"]=[[fb201item48]],["item2"]=[[fb201item49]],["name"]=[[黄泉路]],["permission"]=1,["role1"]=[[fb201r49_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_48]]},["fb201_50"]={["dsc"]=[[这里就是著名的阴间入口「鬼门关」，在你面前矗立著一座高大的黑色城楼，许多亡魂正哭哭啼啼地列队前进，因为一进鬼门关就无法再回阳间了。]],["id"]=[[fb201_50]],["name"]=[[鬼门关]],["permission"]=1,["role1"]=[[fb201r50_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_49]]},["fb201_51"]={["down"]=[[fb201_56]],["dsc"]=[[这条河水呈现红黄色，河水会根据过河者生前的善恶来改变流速。传说不愿喝孟婆汤的人，需要在忘川中承受千年煎熬，就可以带着前世记忆投胎转世。在河岸边生长着鲜红的彼岸花。]],["id"]=[[fb201_51]],["item1"]=[[fb201item24]],["name"]=[[忘川]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb201_52"]={["dsc"]=[[你走进一家温暖的小店，墙角壁炉里微弱的火光将你的影子投射在对面的墙上。几个人影围在炉旁不知在吃什么。门口有一个人正靠在门上打着盹。]],["id"]=[[fb201_52]],["item1"]=[[fb201r52_5]],["left"]=[[fb201_55]],["name"]=[[小店]],["permission"]=1,["role1"]=[[fb201r52_1]],["role2"]=[[fb201r52_2]],["role3"]=[[fb201r52_3]],["role4"]=[[fb201r52_4]],["stepMusic"]=[[jiaobu]]},["fb201_53"]={["dsc"]=[[屋里相当冷清，外面的浓雾还不时地从半开着的门缝飘进来。地面上散着一些破旧的物品，不过光从外表已经无法分辨出那是些什么东西了。墙上刻着一些潦草的字体，墙角的一盏灯笼挣扎似地发出一阵阵微弱的光芒，也使得那些字看来格外的诡异。]],["id"]=[[fb201_53]],["item1"]=[[fb201item14]],["item2"]=[[fb201item15]],["name"]=[[黑店]],["permission"]=1,["role1"]=[[fb201r24_1]],["role2"]=[[fb201item55]],["role3"]=[[fb201item11]],["role4"]=[[fb201item12]],["stepMusic"]=[[jiaobu]]},["fb201_54"]={["down"]=[[fb201_45]],["dsc"]=[[周围光线一下子变暗，灰蒙蒙的一片。却能听到一些急匆匆的脚步声擦身而过。路边随处开着一些梦兰花，发出微光。隐约脚下有条道路，也不知是通向什么地方。]],["id"]=[[fb201_54]],["item1"]=[[fb201item56]],["left"]=[[fb201_54]],["name"]=[[荒郊草野]],["permission"]=1,["right"]=[[fb201_54]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_55]]},["fb201_55"]={["down"]=[[fb201_54]],["dsc"]=[[周围光线一下子变暗，灰蒙蒙的一片。却能听到一些急匆匆的脚步声擦身而过。路边随处开着一些梦兰花，发出微光。隐约脚下有条道路，也不知是通向什么地方。]],["id"]=[[fb201_55]],["left"]=[[fb201_58]],["name"]=[[荒郊草野]],["permission"]=1,["right"]=[[fb201_54]],["role1"]=[[ycitem1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_56]]},["fb201_56"]={["down"]=[[fb201_55]],["dsc"]=[[周围光线一下子变暗，灰蒙蒙的一片。却能听到一些急匆匆的脚步声擦身而过。路边随处开着一些梦兰花，发出微光。隐约脚下有条道路，也不知是通向什么地方。]],["id"]=[[fb201_56]],["left"]=[[fb201_59]],["name"]=[[荒郊草野]],["permission"]=1,["right"]=[[fb201_54]],["role1"]=[[ycitem9]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_57]]},["fb201_57"]={["down"]=[[fb201_56]],["dsc"]=[[周围光线一下子变暗，灰蒙蒙的一片。却能听到一些急匆匆的脚步声擦身而过。路边随处开着一些梦兰花，发出微光。隐约脚下有条道路，也不知是通向什么地方。]],["id"]=[[fb201_57]],["left"]=[[fb201_54]],["name"]=[[荒郊草野]],["permission"]=1,["right"]=[[fb201_60]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_44]]},["fb201_58"]={["down"]=[[fb201_61]],["dsc"]=[[周围光线一下子变暗，灰蒙蒙的一片。却能听到一些急匆匆的脚步声擦身而过。路边随处开着一些梦兰花，发出微光。隐约脚下有条道路，也不知是通向什么地方。]],["id"]=[[fb201_58]],["left"]=[[fb201_54]],["name"]=[[荒郊草野]],["permission"]=1,[