]={["down"]=[[fb201_71]],["dsc"]=[[周围光线一下子变暗，灰蒙蒙的一片。却能听到一些急匆匆的脚步声擦身而过。路边随处开着一些梦兰花，发出微光。隐约脚下有条道路，也不知是通向什么地方。]],["id"]=[[fb201_66]],["name"]=[[荒郊草野]],["permission"]=1,["role1"]=[[zx1item25]],["role2"]=[[zx1item26]],["stepMusic"]=[[jiaobu]]},["fb201_67"]={["dsc"]=[[流经地府的一条冥河。河水从不会起波澜，且深不见底，即使羽毛飘落其上也会转瞬沉入河底，只有专门的渡船可以行之其上。冥河常年雾气弥漫，看不清河面情况，但据说只要把手伸入河中，再举起来时便会变为一堆白骨。河岸边生长着大片水晶兰，当水晶兰盛开之时，冥河之水便会变得清澈，可以看见里面一种通体晶莹的白色小鱼。]],["id"]=[[fb201_67]],["name"]=[[冥河]],["permission"]=1,["role1"]=[[zx1item2]],["stepMusic"]=[[youyong]]},["fb201_68"]={["down"]=[[fb201_73]],["dsc"]=[[周围光线一下子变暗，灰蒙蒙的一片。却能听到一些急匆匆的脚步声擦身而过。路边随处开着一些梦兰花，发出微光。隐约脚下有条道路，也不知是通向什么地方。]],["id"]=[[fb201_68]],["name"]=[[荒郊草野]],["permission"]=1,["role1"]=[[zx1item7]],["stepMusic"]=[[jiaobu]]},["fb201_69"]={["dsc"]=[[这是下阴城中最著名的青楼。这座五层高对角精致的四角阁楼檐角上挂着花铃，时刻摇动着，发出清脆的声响。红花楼的大门从来是紧闭着的，从外面很难窥见里面光景，但推门而入确是香气扑鼻，随处可见饮酒作乐的鬼魂。]],["id"]=[[fb201_69]],["name"]=[[红花楼]],["permission"]=1,["rightDown"]=[[fb201_73]],["role1"]=[[zx10r69_1]],["role2"]=[[zx10r69_2]],["stepMusic"]=[[jiaobu]]},["fb201_70"]={["dsc"]=[[这是下阴城特许开设的赌馆。赌馆中人满为患，各路赌鬼八仙过海各显神通地聚赌着，叫骂声不绝于耳、]],["id"]=[[fb201_70]],["leftDown"]=[[fb201_73]],["name"]=[[财不聚]],["permission"]=1,["role1"]=[[fb201r70_1]],["role2"]=[[fb201r70_2]],["stepMusic"]=[[jiaobu]]},["fb201_71"]={["down"]=[[fb201_75]],["dsc"]=[[这是一座漆黑的城门，城门上写着“上阴北门”。每隔半里便点着一盏青幽幽的灯。此时的城门大开着，站着巡守的鬼差，偶有鬼魂经过城门，便会遇到鬼差严厉的盘查。]],["id"]=[[fb201_71]],["name"]=[[上阴北门]],["permission"]=1,["right"]=[[fb201_103]],["role1"]=[[zx9r71_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_66]]},["fb201_72"]={["dsc"]=[[流经地府的一条冥河。河水从不会起波澜，且深不见底，即使羽毛飘落其上也会转瞬沉入河底，只有专门的渡船可以行之其上。冥河常年雾气弥漫，看不清河面情况，但据说只要把手伸入河中，再举起来时便会变为一堆白骨。河岸边生长着大片水晶兰，当水晶兰盛开之时，冥河之水便会变得清澈，可以看见里面一种通体晶莹的白色小鱼。]],["id"]=[[fb201_72]],["name"]=[[冥河]],["permission"]=1,["role1"]=[[zx1item3]],["stepMusic"]=[[youyong]]},["fb201_73"]={["down"]=[[fb201_89]],["dsc"]=[[这是一座漆黑的城门，城门上写着“下阴北门”。每隔半里便点着一盏青幽幽的灯。此时的城门大开着，站着巡守的鬼差，偶有鬼魂经过城门，便会遇到鬼差严厉的盘查。]],["id"]=[[fb201_73]],["leftDown"]=[[fb201_76]],["leftUp"]=[[fb201_69]],["name"]=[[下阴北门]],["permission"]=1,["rightDown"]=[[fb201_77]],["rightUp"]=[[fb201_70]],["role1"]=[[fb201r73_1]],["role2"]=[[fb201r73_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_68]]},["fb201_74"]={["dsc"]=[[这座酒楼是苏州春在楼先父所开，在冥界生意依然红红火火。只见偌大的酒楼中无一虚席，小二正在忙碌地招呼客人，掌柜端坐在柜台前，笑眯眯地为客人结账。若不是来往者均是面无血色，这里确与阳间无异。]],["id"]=[[fb201_74]],["name"]=[[春在楼]],["permission"]=1,["right"]=[[fb201_75]],["role1"]=[[zx5r74_1]],["role2"]=[[zx1item44]],["stepMusic"]=[[jiaobu]]},["fb201_75"]={["down"]=[[fb201_78]],["dsc"]=[[这是一条阴冷悠长的街道，街上倒也算是热闹，来往的阴魂大多有说有笑，使人觉得恍然如在世。]],["id"]=[[fb201_75]],["left"]=[[fb201_74]],["name"]=[[北阴街]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb201_71]]},["fb201_76"]={["dsc"]=[[下阴城因收留的大多是生前积有恶业的鬼魂，因而设立了类似于阳间衙门的问形司用以管理或惩治在此行凶作恶的鬼。]],["id"]=[[fb201_76]],["name"]=[[问刑司]],["permission"]=1,["rightUp"]=[[fb201_73]],["stepMusic"]=[[jiaobu]]},["fb201_77"]={["dsc"]=[[断头台是用于死后作恶太多的鬼的处刑场所。只见青石台阶之上设置者一排狗头铡，散发着肃杀之气。下阴城中的鬼魂对此地无不远远避开。]],["id"]=[[fb201_77]],["leftUp"]=[[fb201_73]],["name"]=[[断头台]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb201_78"]={["down"]=[[fb201_83]],["dsc"]=[[这是一条阴冷悠长的街道，街上倒也算是热闹，来往的阴魂大多有说有笑，使人觉得恍然如在世。]],["id"]=[[fb201_78]],["name"]=[[北阴街]],["permission"]=1,["right"]=[[fb201_79]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_75]]},["fb201_79"]={["dsc"]=[[一家阴暗的客栈，木制的门槛因潮湿而有些发黑发软。进入店里扑鼻而来的是一股霉味与中药味，店小二正蹲在柜台前煎药。四下一打量，客栈中倒也打扫得干净，只是没什么鬼影。]],["id"]=[[fb201_79]],["left"]=[[fb201_78]],["name"]=[[望归客栈]],["permission"]=1,["role1"]=[[zx11r79_1]],["stepMusic"]=[[jiaobu]]},["fb201_80"]={["down"]=[[fb201_86]],["dsc"]=[[此处往前便是鬼界堡。鬼界堡是冥府中鬼魂居住之所，建有上阴城与下阴城，人死后若非打入地狱者，经过阎王审讯之后业果不同的鬼魂会进入不同的城中等待轮回。]],["id"]=[[fb201_80]],["name"]=[[鬼界堡]],["permission"]=1,["role1"]=[[zx1r80_1]],["role2"]=[[zyr80_1]],["role3"]=[[fb201r24_1]],["stepMusic"]=[[jiaobu]]},["fb201_81"]={["down"]=[[fb201_88]],["dsc"]=[[阴司内寒气森森，正中是一栋闪烁着鬼火的房子。房外有勾司人走来走去。房内是下阴守城鬼差们的办事场所。]],["id"]=[[fb201_81]],["name"]=[[阴司]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb201_82"]={["dsc"]=[[供养阁是接受在世之人供奉给死者之物的地方。在世之人烧给死者的物品钱财都会存放在此处，由鬼差看管，每到清明节与中元节供养阁就会打开，鬼魂可以来此取走给自己的东西。]],["id"]=[[fb201_82]],["name"]=[[供养阁]],["permission"]=1,["rightDown"]=[[fb201_92]],["role1"]=[[zx6r82_1]],["role2"]=[[zx6r82_2]],["role3"]=[[zx1item22]],["stepMusic"]=[[jiaobu]]},["fb201_83"]={["dsc"]=[[这里是鬼界堡上阴城的中心广场。上阴城是生前无恶业的善鬼等待轮回前的暂居之所，除了冥界挥之不去的阴冷的气息，几乎与人间无异。]],["id"]=[[fb201_83]],["leftDown"]=[[fb201_92]],["name"]=[[上阴广场]],["permission"]=1,["right"]=[[fb201_84]],["rightDown"]=[[fb201_93]],["role1"]=[[zx9r83_1]],["role2"]=[[zx9r83_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_78]]},["fb201_84"]={["dsc"]=[[这是一条阴冷悠长的街道，街上倒也算是热闹，来往的阴魂大多有说有笑，使人觉得恍然如在世。]],["id"]=[[fb201_84]],["left"]=[[fb201_83]],["name"]=[[东阴街]],["permission"]=1,["right"]=[[fb201_85]],["stepMusic"]=[[jiaobu]]},["fb201_85"]={["dsc"]=[[这里往前便是鬼界堡的上阴城。只见城门上挂着巨大的“上阴”门匾，漆黑的城门显得十分威严。来往于此地的鬼魂都要经过鬼差的盘查方萌放行，而该入下阴城的鬼魂断然不能进入此地。]],["id"]=[[fb201_85]],["left"]=[[fb201_84]],["name"]=[[上阴门]],["permission"]=1,["right"]=[[fb201_86]],["role1"]=[[zx1r85_1]],["role2"]=[[zx1item42]],["stepMusic"]=[[jiaobu]]},["fb201_86"]={["dsc"]=[[冥河河岸的一片浅滩，插上几根木头做成了码头。冥河岸方圆百里之内只有这一处可以渡河的地方，摆渡人站在小船上，等待着客人来临。]],["id"]=[[fb201_86]],["left"]=[[fb201_85]],["name"]=[[冥河岸]],["permission"]=1,["right"]=[[fb201_87]],["role1"]=[[zx1item4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_80]]},["fb201_87"]={["dsc"]=[[这里往前便是鬼界堡的下阴城。只见城门上挂着巨大的“下阴”门匾，漆黑的城门显得十分威严。来往于此地的鬼魂都要经过鬼差的盘查方萌放行。被押送进下阴城的人在轮回前都不能离开此地。]],["id"]=[[fb201_87]],["left"]=[[fb201_86]],["name"]=[[下阴门]],["permission"]=1,["right"]=[[fb201_88]],["role1"]=[[zx1r87_1]],["role2"]=[[zx1item43]],["stepMusic"]=[[jiaobu]]},["fb201_88"]={["dsc"]=[[这是一条阴冷悠长的街道，街上冷冷清清的，偶尔能听见一丝隐约的呜咽声。]],["id"]=[[fb201_88]],["left"]=[[fb201_87]],["name"]=[[西幽街]],["permission"]=1,["right"]=[[fb201_89]],["role1"]=[[zx1item6]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_81]]},["fb201_89"]={["down"]=[[fb201_95]],["dsc"]=[[这里是鬼界堡下阴城的中心广场。下阴城是生前积有恶业但罪不至十恶不赦的鬼等待轮回前的暂居之所，除了冥界挥之不去的阴冷的气息，几乎与人间无异。]],["id"]=[[fb201_89]],["left"]=[[fb201_88]],["name"]=[[下阴广场]],["permission"]=1,["right"]=[[fb201_90]],["role1"]=[[zx3r89_1]],["role2"]=[[zx3r89_2]],["role3"]=[[fb201r89_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_73]]},["fb201_90"]={["dsc"]=[[这是一条阴冷悠长的街道，街上冷冷清清的，偶尔能听见一丝隐约的呜咽声。]],["id"]=[[fb201_90]],["left"]=[[fb201_89]],["name"]=[[东幽街]],["permission"]=1,["right"]=[[fb201_91]],["role1"]=[[zx3r90_1]],["role2"]=[[zx8r90_1]],["stepMusic"]=[[jiaobu]]},["fb201_91"]={["dsc"]=[[这是一座漆黑的城门，城门上写着“下阴东门”。每隔半里便点着一盏青幽幽的灯。此时的城门大开着，站着巡守的鬼差，偶有鬼魂经过城门，便会遇到鬼差严厉的盘查。]],["id"]=[[fb201_91]],["left"]=[[fb201_90]],["name"]=[[下阴东门]],["permission"]=1,["role1"]=[[zx8r91_1]],["role2"]=[[zx1item35]],["stepMusic"]=[[jiaobu]]},["fb201_92"]={["dsc"]=[[这是一条阴冷悠长的街道，街上倒也算是热闹，来往的阴魂大多有说有笑，使人觉得恍然如在世。]],["id"]=[[fb201_92]],["leftDown"]=[[fb201_96]],["leftUp"]=[[fb201_82]],["name"]=[[西阴街]],["permission"]=1,["rightUp"]=[[fb201_83]],["role1"]=[[fb201r92_1]],["stepMusic"]=[[jiaobu]]},["fb201_93"]={["down"]=[[fb201_97]],["dsc"]=[[这是一条阴冷悠长的街道，街上倒也算是热闹，来往的阴魂大多有说有笑，使人觉得恍然如在世。]],["id"]=[[fb201_93]],["leftUp"]=[[fb201_83]],["name"]=[[南阴街]],["permission"]=1,["right"]=[[fb201_94]],["stepMusic"]=[[jiaobu]]},["fb201_94"]={["dsc"]=[[这是一座鬼居所，外形与阳间无异。房内有一口巨大的打铁炉，铁炉中跳跃着青色的阴火。房间中到处堆放着铁块与打造出来的兵器，弥漫着铁器特有的森然之气。一名发须皆白的驼背老者正在铁炉前打铁。]],["id"]=[[fb201_94]],["left"]=[[fb201_93]],["name"]=[[冥居]],["permission"]=1,["role1"]=[[zx4r94_1]],["role2"]=[[zx1item14]],["role3"]=[[zx1item15]],["stepMusic"]=[[jiaobu]]},["fb201_95"]={["down"]=[[fb201_98]],["dsc"]=[[这是一座漆黑的城门，城门上写着“下阴南门”。每隔半里便点着一盏青幽幽的灯。此时的城门大开着，站着巡守的鬼差，偶有鬼魂经过城门，便会遇到鬼差严厉的盘查。]],["id"]=[[fb201_95]],["name"]=[[下阴南门]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb201_89]]},["fb201_96"]={["down"]=[[fb201_99]],["dsc"]=[[这是一条阴冷悠长的街道，街上倒也算是热闹，来往的阴魂大多有说有笑，使人觉得恍然如在世。]],["id"]=[[fb201_96]],["name"]=[[西阴街]],["permission"]=1,["rightUp"]=[[fb201_92]],["stepMusic"]=[[jiaobu]]},["fb201_97"]={["down"]=[[fb201_100]],["dsc"]=[[这是一条阴冷悠长的街道，街上倒也算是热闹，来往的阴魂大多有说有笑，使人觉得恍然如在世。]],["id"]=[[fb201_97]],["name"]=[[南阴街]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb201_93]]},["fb201_98"]={["dsc"]=[[这里是一片瓒枯木长成的树林。瓒枯木生长自地狱烈火之中，会结出一种火红色的果实，这种果实对香气对鬼魂有着无法抵挡的诱惑，但只要经不住诱惑吃下瓒枯木果实，便会永堕火山地狱。]],["id"]=[[fb201_98]],["item1"]=[[ycitem11]],["name"]=[[瓒枯木丛]],["permission"]=1,["role1"]=[[zx4r98_1]],["role2"]=[[zx1item8]],["role3"]=[[zx1item9]],["role4"]=[[zx1item10]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_95]]},["fb201_99"]={["dsc"]=[[一家贩卖寿衣的小店，铺面堆满了各式各样的寿衣，连店面的装饰都几乎被完全掩盖。拨开寿衣四下打望却没有鬼影，此时如果回头便会见到寿衣店掌柜穿着最新式的寿衣悄无声息地站在身后，鬼气森森地无声笑着注视着进来的客人。]],["id"]=[[fb201_99]],["name"]=[[寿衣店]],["permission"]=1,["role1"]=[[zx1item29]],["role2"]=[[zx1item30]],["role3"]=[[zx1item31]],["stepMusic"]=[[jiaobu]],["up"]=[[fb201_96]]}}00000